import{_ as e,o as d,c as o,a0 as c}from"./chunks/framework.M9bIWcU1.js";const m=JSON.parse('{"title":"Checks Reference Guide","description":"","frontmatter":{},"headers":[],"relativePath":"checks-reference.md","filePath":"checks-reference.md"}'),i={name:"checks-reference.md"};function r(s,t,a,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="checks-reference-guide" tabindex="-1">Checks Reference Guide <a class="header-anchor" href="#checks-reference-guide" aria-label="Permalink to &quot;Checks Reference Guide&quot;">​</a></h1><p>This document lists all active checks in the <code>laravel-integrity</code> pipeline.</p><table tabindex="0"><thead><tr><th>Key</th><th>Name</th><th>Severity</th><th>Fixable</th><th>Expensive</th><th>Description</th></tr></thead><tbody><tr><td><code>strict-types</code></td><td>Strict Types Declaration</td><td><code>Low</code></td><td>Yes</td><td>No</td><td>Enforces <code>declare(strict_types=1);</code> is present as the first statement in PHP files.</td></tr><tr><td><code>root-facade</code></td><td>Root Namespace Facades</td><td><code>Low</code></td><td>Yes</td><td>No</td><td>Replaces root facade references (e.g. <code>\\DB::</code>) with clean imports.</td></tr><tr><td><code>direct-env</code></td><td>Direct Env Calls</td><td><code>Medium</code></td><td>No</td><td>No</td><td>Prohibits direct calls to <code>env()</code> outside config files.</td></tr><tr><td><code>unused-import</code></td><td>Unused Import Statements</td><td><code>Low</code></td><td>Yes</td><td>No</td><td>Identifies and removes unused <code>use</code> declarations.</td></tr><tr><td><code>missing-named-route</code></td><td>Missing Named Routes</td><td><code>High</code></td><td>No</td><td>No</td><td>Verifies that calls to <code>route(&#39;name&#39;)</code> map to valid routes.</td></tr><tr><td><code>missing-view-path</code></td><td>Missing View Paths</td><td><code>High</code></td><td>No</td><td>No</td><td>Verifies that calls to <code>view(&#39;name&#39;)</code>, <code>@include(&#39;name&#39;)</code>, and <code>@extends(&#39;name&#39;)</code> exist on disk.</td></tr><tr><td><code>orphaned-component</code></td><td>Orphaned Components</td><td><code>Medium</code></td><td>No</td><td>No</td><td>Verifies that custom Blade tags (e.g. <code>&lt;x-alert /&gt;</code>) resolve to components or views.</td></tr><tr><td><code>livewire-manifest</code></td><td>Livewire Manifest Check</td><td><code>Critical</code></td><td>No</td><td>No</td><td>Verifies that <code>&lt;livewire:name /&gt;</code> and <code>@livewire(&#39;name&#39;)</code> map to registered Livewire aliases.</td></tr><tr><td><code>wire-action-method</code></td><td>Livewire Action Methods</td><td><code>Critical</code></td><td>No</td><td>No</td><td>Asserts that methods bound via <code>wire:click=&quot;...&quot;</code> exist and are public.</td></tr><tr><td><code>wire-visibility</code></td><td>Livewire Property Visibility</td><td><code>High</code></td><td>No</td><td>No</td><td>Asserts that fields bound via <code>wire:model=&quot;...&quot;</code> exist and are public on the component class.</td></tr><tr><td><code>route-serialization</code></td><td>Route Serialization</td><td><code>High</code></td><td>No</td><td>Yes</td><td>Flags Closure routes that prevent route caching (<code>route:cache</code>).</td></tr><tr><td><code>dangling-controller</code></td><td>Dangling Controller Actions</td><td><code>Critical</code></td><td>No</td><td>Yes</td><td>Asserts that routes map to valid controllers and public methods.</td></tr><tr><td><code>blade-compile</code></td><td>Blade Compile Check</td><td><code>High</code></td><td>No</td><td>Yes</td><td>Sandboxes Blade views to catch syntax and compilation errors.</td></tr><tr><td><code>seeder-exists</code></td><td>Seeder Class Existence</td><td><code>High</code></td><td>No</td><td>No</td><td>Verifies that classes invoked in <code>$this-&gt;call([...])</code> inside database seeders exist.</td></tr><tr><td><code>pending-migration</code></td><td>Pending Migrations</td><td><code>High</code></td><td>No</td><td>Yes</td><td>Flags migrations that exist on disk but have not been executed.</td></tr><tr><td><code>migration-syntax</code></td><td>Migration Syntax Check</td><td><code>Critical</code></td><td>No</td><td>No</td><td>Parses migrations to assert they compile cleanly.</td></tr><tr><td><code>model-table-mapping</code></td><td>Model Table Mapping</td><td><code>High</code></td><td>No</td><td>Yes</td><td>Verifies that Eloquent models correspond to existing database tables.</td></tr><tr><td><code>dead-provider</code></td><td>Dead Service Providers</td><td><code>Critical</code></td><td>No</td><td>No</td><td>Flags service provider configurations mapping to missing classes.</td></tr><tr><td><code>policy-mapping</code></td><td>Policy Method Mapping</td><td><code>Medium</code></td><td>No</td><td>Yes</td><td>Verifies that authorization abilities map to public policy methods.</td></tr><tr><td><code>event-listener-mapping</code></td><td>Event Listener Mappings</td><td><code>High</code></td><td>No</td><td>Yes</td><td>Asserts that event listener callbacks exist and are public.</td></tr></tbody></table>',3)])])}const u=e(i,[["render",r]]);export{m as __pageData,u as default};
